import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const out='/tmp/legendgirl-polimento-cenas';
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='EASY';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);

 const report=await evaluate(`(async()=>{
   const {createGardenState,restoreGardenState}=await import('/src/js/garden/GardenSimulation.js');
   const wait=ms=>new Promise(r=>setTimeout(r,ms)),key=(code,repeat=false)=>{window.dispatchEvent(new KeyboardEvent('keydown',{code,repeat,bubbles:true,cancelable:true}));window.dispatchEvent(new KeyboardEvent('keyup',{code,bubbles:true}));};
   phase.state=createGardenState('EASY');game.setPaused(false);await wait(400);const age=phase.state.age;await wait(1200);if(phase.state.story.openingIndex!==0||phase.state.age<=age)throw Error('Espera ou atuação inválida');
   key('KeyS');await wait(80);if(phase.state.story.openingDone)throw Error('Pulou cena inédita');
   key('Enter');await wait(80);for(let i=0;i<4;i++)key('Enter',true);await wait(100);if(phase.state.story.openingIndex!==1)throw Error('Repetição atravessou falas');
   const saved=phase.snapshot();phase.state=restoreGardenState(saved.state,'EASY');if(phase.state.story.openingIndex!==1)throw Error('Leitura não restaurada');
   game.setPaused(true);const paused=JSON.stringify(phase.state);await wait(300);if(JSON.stringify(phase.state)!==paused)throw Error('Estado mudou pausado');game.setPaused(false);
   const rect=phase.canvas.getBoundingClientRect();phase.canvas.dispatchEvent(new PointerEvent('pointerdown',{pointerId:37,button:0,clientX:rect.left+rect.width/2,clientY:rect.top+rect.height/2,bubbles:true,cancelable:true}));phase.canvas.dispatchEvent(new PointerEvent('pointerup',{pointerId:37,bubbles:true}));await wait(80);if(phase.state.story.openingIndex!==2)throw Error('Toque não avançou exatamente uma fala');
   for(let i=2;i<9;i++){key(i===8?'Space':'Enter');await wait(90);}await wait(3400);if(phase.state.stage!=='RUNNING'||phase.state.jumps!==0)throw Error('Transição provocou salto ou não terminou');
   const seen=JSON.parse(localStorage.getItem('legendgirl:garden:scenes:v1'));if(!seen.opening)throw Error('Cena vista não persistida');
   phase.state=createGardenState('EASY');phase.state.story.seenOpening=seen.opening;phase.render();const box=phase.renderer.storyControls.skip,r=phase.canvas.getBoundingClientRect();if(!box)throw Error('Atalho visto ausente');phase.canvas.dispatchEvent(new PointerEvent('pointerdown',{pointerId:38,button:0,clientX:r.left+(box.x+box.w/2)*r.width/phase.canvas.width,clientY:r.top+(box.y+box.h/2)*r.height/phase.canvas.height,bubbles:true,cancelable:true}));phase.canvas.dispatchEvent(new PointerEvent('pointerup',{pointerId:38,bubbles:true}));await wait(3300);if(phase.state.stage!=='RUNNING')throw Error('Cena vista não pôde ser pulada');
   game.setPaused(true);return{espera:true,teclaMantida:true,toque:true,pausa:true,saveLeitura:true,semPuloDeTransicao:true,skipVistoPorToque:true};
 })()`);
 const scenes=[];
 for(const [name,width,height]of [['desktop',1280,800],['retrato',390,844],['paisagem',844,390]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:name!=='desktop'});await new Promise(r=>setTimeout(r,120));
  const shots=await evaluate(`(async()=>{const {createGardenState}=await import('/src/js/garden/GardenSimulation.js');game.setPaused(true);const shots=[];phase.state=createGardenState('EASY');phase.state.stage='COMPLETE';for(let i=0;i<10;i++){game.setPaused(false);window.dispatchEvent(new KeyboardEvent('keydown',{code:'Enter'}));window.dispatchEvent(new KeyboardEvent('keyup',{code:'Enter'}));if(i===0){phase.input.clear();}await new Promise(r=>setTimeout(r,120));game.setPaused(true);phase.render();shots.push({index:phase.state.story.endingIndex,image:phase.canvas.toDataURL()});}return shots;})()`);
  for(let i=0;i<shots.length;i++)await writeFile(out+'/'+name+'-final-'+i+'.png',Buffer.from(shots[i].image.split(',')[1],'base64'));
  scenes.push({name,indices:shots.map(s=>s.index)});
 }
 await writeFile('docs/diario-ia/qa-resultados/yuna/leitura-polimento.json',JSON.stringify({report,scenes},null,2));console.log(JSON.stringify({report,scenes}));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
